// A large table delivered as a beast2 file. Only the path travels in the
// package; deploy checks the file against the declared type and takes it in
// as the value — a collection a segment at a time, as the store's own
// segments, never read whole and never modified — so a new delivery stores
// only the segments that changed, and only its consumers re-run.
const RowType = StructType({ id: IntegerType, site: StringType });
const table = e3.input('table', ArrayType(RowType), variant('file', './deliveries/TABLE.beast2'));

// Point it at a new delivery without a redeploy:
//   e3 dataset set . dev.table --from-file ./deliveries/TABLE-v2.beast2

// Bundle into a package — pass the last tasks: what they depend on is collected —
// and export it to a zip.
const input = e3.input('input', IntegerType, variant('value', 21n));
const finalTask = e3.task('final_task', [input], East.function([IntegerType], IntegerType, ($, x) => x.multiply(2n)));

const pkg = e3.package('myapp', '1.0.0', finalTask);
await e3.export(pkg, '/tmp/myapp.zip');
export default pkg;

// Complete e3 package with input, task, package, and export
const name = e3.input('name', StringType, variant('value', 'World'));

const greet = e3.task(
  'greet',
  [name],
  East.function([StringType], StringType, ($, n) =>
    East.str`Hello, ${n}!`
  )
);

const pkg = e3.package('hello', '1.0.0', greet);
await e3.export(pkg, '/tmp/hello.zip');
export default pkg;

const url = 'http://localhost:3000';            // e3-api-server --repos ./repos
const opts = { token: null };                   // a server with auth: the token `e3 auth token <server>` prints

await repoCreate(url, 'demo', opts);
const pkg = await packageImport(url, 'demo', readFileSync('hello.zip'), opts);
await workspaceCreate(url, 'demo', 'dev', opts);
await workspaceDeploy(url, 'demo', 'dev', `${pkg.name}@${pkg.version}`, opts);   // a job, polled to its end

const run = await dataflowExecute(url, 'demo', 'dev', {}, opts);                  // starts the run and polls it
// A dataset's path is a TreePath — a definition's `.path`, or built from its fields:
const greeting = [variant('field', 'tasks'), variant('field', 'greet'), variant('field', 'output')];
const { data } = await datasetGet(url, 'demo', 'dev', greeting, opts);
console.log(run.success, decodeBeast2For(StringType)(data));                     // true 'Hello, World!'

// Source/IR input -> PNG (and optional standalone HTML):
await renderToPng({
  input: { path: './dashboard.tsx' },
  output: 'dashboard.png',
  html: 'dashboard.html',
});

// A deployed e3 task's computed output:
await renderTaskToPng({ repo: './.repos', workspace: 'main', task: 'dashboard', output: 'dashboard.png' });

const RowType = StructType({ id: StringType, at: IntegerType });

// A producer has no inputs: it reads platform sources (paged APIs, database
// cursors) and emits. Emission order is free — the runner sorts a Dict output
// in runs of bounded size — and a key emitted twice folds with `merge`: here
// the latest row wins.
const rows = e3.streamTask('ingest', {
  inputs: [],
  output: e3.output.dict(StringType, RowType, {
    merge: ($, _id, a, b) => East.greater(a.at, b.at).ifElse(($) => a, ($) => b),
  }),
}, ($, emit) => { /* fetch pages, $(emit(row.id, row)) each */ });

const OrderLineType = StructType({ sku: StringType, quantity: IntegerType });
const QuoteType = StructType({ total: FloatType, short: ArrayType(StringType) });

const prices = e3.input('prices', DictType(StringType, FloatType), variant('value', new Map([['bolt', 0.25]])));
const stock = e3.input('stock', DictType(StringType, IntegerType), variant('value', new Map([['bolt', 500n]])));

// `inputs` (an input, a task's output or a record) are read from the workspace
// at each call, pinned at their hashes; `args` are what the caller passes. The
// body takes the inputs, then the arguments. Nothing reruns when an input
// changes: a function is no node of the dataflow.
const quote = e3.function('quote', {
  inputs: [prices, stock],
  args: [ArrayType(OrderLineType)],
  output: QuoteType,
}, ($, prices, stock, lines) => {
  const total = $.let(0.0);
  const short = $.let([], ArrayType(StringType));
  $.for(lines, ($, line) => {
    $.assign(total, total.add(prices.get(line.sku, () => 0.0).multiply(line.quantity.toFloat())));
    $.if(East.less(stock.get(line.sku, () => 0n), line.quantity), ($) => { $(short.pushLast(line.sku)); });
  });
  return { total, short };
});

export default e3.package('shop', '1.0.0', quote);   // collects prices and stock

// Called through a workspace, with the order alone:
//   e3 call . -w dev quote '[(sku="bolt", quantity=120)]'
// On a page: Func.bind(quote).call(order) — the page binds neither dataset.

// unit.worker.ts — where East programs run: east-web-std answers for east-node-std's
// platform functions, and e3's own (e3-api-client's Platform) reach the e3 worker
import { serveUnits } from '@elaraai/e3-web/units';
serveUnits();

// e3.worker.ts — e3 itself: its storage, orchestrator, runner and API
import { serveE3 } from '@elaraai/e3-web/worker';
serveE3({
  units: () => new Worker(new URL('./unit.worker.ts', import.meta.url), { type: 'module' }),
});

// main.ts — the page: e3-api-client's calls, every one answered by the e3 worker
import { createWebE3 } from '@elaraai/e3-web';
import {
  dataflowExecute, packageImport, repoCreate, repoList, workspaceCreate, workspaceDeploy,
} from '@elaraai/e3-api-client';

const e3 = await createWebE3(new Worker(new URL('./e3.worker.ts', import.meta.url), { type: 'module' }));
const opts = { token: null, fetch: e3.fetch };

// The first visit makes the repository; later visits find it where they left it.
if (!(await repoList(e3.apiUrl, opts)).includes('default')) {
  await repoCreate(e3.apiUrl, 'default', opts);
  // The package zip e3.export wrote at build time, served beside the page
  const zip = new Uint8Array(await (await fetch('/sales-planning-1.0.0.zip')).arrayBuffer());
  const { name, version } = await packageImport(e3.apiUrl, 'default', zip, opts);
  await workspaceCreate(e3.apiUrl, 'default', 'main', opts);
  await workspaceDeploy(e3.apiUrl, 'default', 'main', `${name}@${version}`, opts);
  await dataflowExecute(e3.apiUrl, 'default', 'main', {}, opts);
}

// unit.worker.ts — an app's own platform package, served beside east-web-std's and e3's own.
// A task lists it as its runner lists any package: { custom: '@acme/pricing' }
import { East, FloatType } from '@elaraai/east';
import { serveUnits } from '@elaraai/e3-web/units';

const price = East.platform('acme.price', [FloatType], FloatType);
serveUnits({ platforms: { '@acme/pricing': [price.implement((x: number) => x * 1.1)] } });

// e3.worker.ts — callers known by their tokens, and granted by their roles
import { serveE3, type Identity } from '@elaraai/e3-web/worker';

const callers = new Map<string, Identity>([
  ['Bearer admin-token', { sub: 'admin', roles: ['admin'] }],
  ['Bearer analyst-token', { sub: 'analyst', roles: [] }],
]);

serveE3({
  units: () => new Worker(new URL('./unit.worker.ts', import.meta.url), { type: 'module' }),
  // An unknown caller is answered 401; `access` is then oneShotAccessByRoles():
  // an admin's or owner's one-shots run `any`, every other caller's `platform_free`
  identify: (request) => callers.get(request.headers.get('authorization') ?? ''),
  persist: true,   // false: repositories in memory, gone with the page
  name: 'e3',      // e3 workers of one name share their repositories, in one tab or several
});

// main.tsx — a deployed ui() task, every request it makes answered in the page
const e3 = await createWebE3(new Worker(new URL('./e3.worker.ts', import.meta.url), { type: 'module' }));

createRoot(document.getElementById('root')!).render(
  <ChakraProvider value={system}>
    <E3Provider config={{ apiUrl: e3.apiUrl, repo: 'default', workspace: 'main', fetch: e3.fetch }}>
      <ReactiveDatasetProvider>
        <UITaskPreview task="dashboard" />
      </ReactiveDatasetProvider>
    </E3Provider>
  </ChakraProvider>,
);
